CREATE OR REPLACE FUNCTION ecb7.applicability(c jsonb, observation uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare obs jsonb; k text; v jsonb; gaps jsonb:='[]'; begin
 obs:=ecb7.doc(observation,'b7_observation');
 for k,v in select * from jsonb_each(c->'dependencies') loop
  if not(obs->'dependencies' ? k) then gaps:=gaps||jsonb_build_array(jsonb_build_object('dependency',k,'reason','observation_unavailable'));
  elsif obs->'dependencies'->k is distinct from v then gaps:=gaps||jsonb_build_array(jsonb_build_object('dependency',k,'reason','dependency_changed','expected',v,'observed',obs->'dependencies'->k)); end if;
 end loop;
 return jsonb_build_object('applicable',jsonb_array_length(gaps)=0,'gaps',gaps,'observation',observation,'limits',obs->'limits');
end $function$

CREATE OR REPLACE FUNCTION ecb7.attempt(i uuid, candidate uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c jsonb; s ecb7.scopes; prior jsonb; j jsonb; begin
 c:=ecb7.doc(candidate,'b7_candidate');
 select * into strict s from ecb7.scopes where id=(select context_id from public.artifacts where id=candidate);
 j:=jsonb_build_object('candidate',candidate,'scope',s.id,'contract',s.contract,'basis',c,'status','pending');
 if exists(select 1 from public.artifacts where id=i) then
  prior:=ecb7.doc(i,'b7_attempt'); if prior<>j then raise exception 'request_conflict'; end if; return i;
 end if;
 return ecb7.retain('b7_attempt',candidate,j,i);
end $function$

CREATE OR REPLACE FUNCTION ecb7.designate(request uuid, sid uuid, candidate uuid, evaluation uuid, predecessor uuid, grant_id uuid, observation uuid, operation text DEFAULT 'select'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s ecb7.scopes; g jsonb; q jsonb; c jsonb; req jsonb; prior jsonb; event uuid; app jsonb; moment timestamptz; begin
 select * into strict s from ecb7.scopes where id=sid for update;
 req:=jsonb_build_object('scope',sid,'candidate',candidate,'evaluation',evaluation,'predecessor',predecessor,'grant',grant_id,'observation',observation,'operation',operation,'actor',session_user);
 if exists(select 1 from public.artifacts where id=request) then
  prior:=ecb7.doc(request,'b7_attempt');
  if prior is distinct from req then raise exception 'request_conflict'; end if;
  select id into event from public.artifacts where context_id=request and artifact_role='b7_designation';
  if event is null then raise exception 'unknown_commit_outcome'; end if;
  return jsonb_build_object('event',event,'recovered',true,'present_current',s.current_event=event);
 end if;
 if operation not in ('select','withdraw') then raise exception 'operation_mismatch'; end if;
 g:=ecb7.doc(grant_id,'b7_grant');
 if g->>'synthetic' is distinct from 'true' or g->>'issuer' is distinct from 'G_TEST' then raise exception 'fixture_authority_only'; end if;
 if g->>'actor' is distinct from session_user or g->>'scope' is distinct from sid::text or g->>'operation' is distinct from operation
 or g->>'candidate' is distinct from candidate::text or g->>'evaluation' is distinct from evaluation::text
 or g->>'predecessor' is distinct from predecessor::text then raise exception 'grant_tuple_mismatch'; end if;
 if g->>'temporal' is null or g->'temporal'->>'act' is null or g->'temporal'->>'continuing_effect' is null then raise exception 'temporal_applicability_required'; end if;
 moment:=clock_timestamp();
 if g->'temporal'->>'act'='interval' then
  if g->'temporal'->>'from' is null or g->'temporal'->>'until' is null or moment<(g->'temporal'->>'from')::timestamptz or moment>=(g->'temporal'->>'until')::timestamptz then raise exception 'grant_expired_or_not_yet_applicable'; end if;
 elsif g->'temporal'->>'act'<>'until_revoked' then raise exception 'unknown_temporal_rule'; end if;
 if (ecb7.doc(observation,'b7_observation')->'revoked_grants') is null then raise exception 'revocation_observation_required'; end if;
 if ecb7.doc(observation)->'revoked_grants' ? grant_id::text then raise exception 'grant_revoked'; end if;
 if (select context_id from public.artifacts where id=observation)<>sid then raise exception 'observation_scope'; end if;
 if s.current_event is distinct from predecessor then raise exception 'stale_predecessor'; end if;
 c:=ecb7.doc(candidate,'b7_candidate'); q:=ecb7.doc(evaluation,'b7_evaluation');
 if q->>'outcome' is distinct from 'PASS' then raise exception 'qualification_not_pass'; end if;
 if q->>'candidate' is distinct from candidate::text or q->>'scope' is distinct from sid::text or q->'basis' is distinct from c
 or c->>'contract' is distinct from s.contract::text or q->>'contract' is distinct from s.contract::text then raise exception 'qualification_tuple'; end if;
 app:=ecb7.applicability(c,observation);
 if app->>'applicable' is distinct from 'true' then raise exception 'requalification_required'; end if;
 if (q->'applicability'->>'mode') is distinct from 'declared_dependencies' then raise exception 'qualification_applicability_required'; end if;
 if g->'temporal'->>'continuing_effect' not in ('historical_act_only','unrevoked') then raise exception 'unknown_continuing_effect'; end if;
 perform ecb7.retain('b7_attempt',sid,req,request);
 event:=ecb7.retain('b7_designation',request,req||jsonb_build_object('temporal',g->'temporal','occurred_at',moment,
 'qualification_applicability',app,'execution_authorized',false));
 update ecb7.scopes set current_event=event where id=sid;
 return jsonb_build_object('event',event,'recovered',false,'present_current',true);
end $function$

CREATE OR REPLACE FUNCTION ecb7.doc(i uuid, role_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare r public.artifacts; begin
 select * into r from public.artifacts where id=i;
 if not found then raise exception 'exact_payload_unavailable:%',i; end if;
 if role_name is not null and r.artifact_role<>role_name then raise exception 'wrong_artifact_role'; end if;
 if r.payload_digest<>extensions.digest(convert_to(r.payload_text,'UTF8'),'sha256') then raise exception 'integrity_mismatch'; end if;
 return r.payload_text::jsonb;
end $function$

CREATE OR REPLACE FUNCTION ecb7.fixture(k text, c uuid, j jsonb, i uuid DEFAULT gen_random_uuid())
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ begin
 if k not in ('b7_grammar','b7_snapshot','b7_contract','b7_grant') then raise exception 'fixture_role'; end if;
 if j->>'synthetic' is distinct from 'true' then raise exception 'synthetic_only'; end if;
 return ecb7.retain(k,c,j,i);
end $function$

CREATE OR REPLACE FUNCTION ecb7.observe(s uuid, j jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ begin
 if not exists(select 1 from ecb7.scopes where id=s) then raise exception 'unknown_scope'; end if;
 if j->>'route' is null or jsonb_typeof(j->'dependencies') is distinct from 'object' then raise exception 'observation_route_required'; end if;
 return ecb7.retain('b7_observation',s,j||jsonb_build_object('observer',session_user));
end $function$

CREATE OR REPLACE FUNCTION ecb7.prepare_artifact()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare j jsonb; c jsonb; begin
 if new.payload_digest is not null or new.recorded_at is not null or new.created_xid is not null then raise exception 'derived_columns'; end if;
 if new.payload_text is null or not(new.payload_text is json object with unique keys) then raise exception 'exact_json_object_required'; end if;
 j:=new.payload_text::jsonb;
 if new.artifact_role<>'b7_candidate' and current_user<>'ecb7_owner' then raise exception 'protected_build7_role'; end if;
 if new.artifact_role='b7_candidate' then
  if not exists(select 1 from ecb7.scopes where id=new.context_id) then raise exception 'unknown_scope'; end if;
  -- Preserve defective semantic candidates for C2 inspection; producer flags cannot confer eligibility.
  if j->>'focal' is null or j->>'grammar' is null or j->>'contract' is null then raise exception 'candidate_manifest_required'; end if;
 end if;
 if exists(select 1 from public.referents where id=new.id) then raise exception 'identity_already_registered'; end if;
 insert into public.referents(id) values(new.id);
 new.payload_digest:=extensions.digest(convert_to(new.payload_text,'UTF8'),'sha256');
 new.recorded_at:=transaction_timestamp(); new.created_xid:=pg_current_xact_id();
 return new;
end $function$

CREATE OR REPLACE FUNCTION ecb7.publish(a uuid, findings jsonb, method text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare req jsonb; ct jsonb; r uuid; outcome text; f jsonb; wanted text[]; got text[]; begin
 req:=ecb7.doc(a,'b7_attempt'); ct:=ecb7.doc((req->>'contract')::uuid,'b7_contract');
 if (select created_xid from public.artifacts where id=a)=pg_current_xact_id() then raise exception 'committed_attempt_required'; end if;
 if ct->>'method' is distinct from method then raise exception 'method_binding'; end if;
 select array_agg(x order by x) into wanted from jsonb_array_elements_text(ct->'obligations') x;
 select array_agg(x->>'obligation' order by x->>'obligation') into got from jsonb_array_elements(findings) x;
 if wanted is distinct from got or array_length(got,1) is null then raise exception 'obligation_coverage'; end if;
 for f in select * from jsonb_array_elements(findings) loop
  if f->>'status' is null or f->>'status' not in ('PASS','FAIL','INCOMPLETE','INDETERMINATE') or length(coalesce(f->>'reason',''))=0
   or f->'witness' is null then raise exception 'finding_basis_required'; end if;
 end loop;
 if exists(select 1 from jsonb_array_elements(findings) entry where entry->>'status'='FAIL') then outcome:='FAIL';
 elsif exists(select 1 from jsonb_array_elements(findings) entry where entry->>'status'='INCOMPLETE') then outcome:='INCOMPLETE';
 elsif exists(select 1 from jsonb_array_elements(findings) entry where entry->>'status'='INDETERMINATE') then outcome:='INDETERMINATE'; else outcome:='PASS'; end if;
 -- Serialize exact terminal publication. Changed findings are not accepted as retry.
 perform pg_advisory_xact_lock(hashtextextended(a::text,7));
 select id into r from public.artifacts where artifact_role='b7_evaluation' and context_id=a;
 if found then
  if ecb7.doc(r)->'findings'<>findings or ecb7.doc(r)->>'method'<>method then raise exception 'terminal_conflict'; end if; return r;
 end if;
 return ecb7.retain('b7_evaluation',a,jsonb_build_object('attempt',a,'candidate',req->'candidate','scope',req->'scope',
 'contract',req->'contract','basis',req->'basis','method',method,'evaluator',session_user,'findings',findings,'outcome',outcome,
 'meaning','bounded_comparison_only','applicability',ct->'applicability','execution_authorized',false));
end $function$

CREATE OR REPLACE FUNCTION ecb8.authorize(s uuid, a uuid, envelope uuid, evaluation uuid, grant_id uuid, selection_prior uuid, p uuid, request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare h jsonb; c jsonb; q jsonb; g jsonb; req jsonb; prior jsonb; eid uuid; begin
 perform ecb8.lock_scope(s); h:=ecb8.history(s,a);
 req:=jsonb_build_object('authorization',jsonb_build_object('envelope',envelope,'evaluation',evaluation,'grant',grant_id),
 'designation',jsonb_build_object('envelope',envelope,'predecessor',selection_prior));
 select x into prior from jsonb_array_elements(h->'events') x where x->>'request'=request::text;
 if prior is not null then
  if prior->>'kind'<>'authorize' or prior->>'login'<>session_user or (prior->'data')-'tick' is distinct from req
   or prior->>'predecessor' is distinct from p::text then raise exception 'b8_request_conflict'; end if;
  return jsonb_build_object('event',prior->'id','replayed',true,'historical_authorization',prior->'data',
    'present_selected',h->'selected'->>'id'=prior->>'id');
 end if;
 perform ecb8.expected(h,p);
 c:=ecb8.doc(envelope,'b8_envelope'); q:=ecb8.doc(evaluation,'b8_evaluation'); g:=ecb8.doc(grant_id,'b8_basis');
 if c->>'scope' is distinct from s::text or c->>'action' is distinct from a::text
 or c->>'actor' is distinct from h->'initial'->'principals'->>session_user
 or h->'initial'->>'actor_login' is distinct from session_user then raise exception 'b8_actor_action_binding'; end if;
 if q->>'outcome' is distinct from 'PASS' or q->>'envelope' is distinct from envelope::text
 or q->>'method' is distinct from c->>'method' or q->>'contract' is distinct from c->>'contract' then raise exception 'b8_qualification_binding'; end if;
 if g->>'kind' is distinct from 'grant' or g->>'issuer' is distinct from 'A_TEST'
 or g->>'login' is distinct from session_user or g->>'actor' is distinct from c->>'actor'
 or g->>'scope' is distinct from s::text or g->>'action' is distinct from a::text or g->>'target' is distinct from c->>'target'
 or g->>'operation' is distinct from 'advance_one' or g->>'envelope' is distinct from envelope::text
 or g->>'evaluation' is distinct from evaluation::text or g->>'predecessor' is distinct from selection_prior::text
 or g->'temporal' is distinct from c->'temporal' or g->'rights' is distinct from '["withdraw","revoke"]'::jsonb then raise exception 'b8_grant_tuple'; end if;
 if h->>'selection_head' is distinct from selection_prior::text then raise exception 'b8_stale_selection'; end if;
 if h->'revoked_grants' ? grant_id::text then raise exception 'b8_grant_revoked'; end if;
 if ecb8.conditions(h,envelope,'authorize')<>'[]'::jsonb then raise exception 'b8_authorization_conditions:%',ecb8.conditions(h,envelope,'authorize'); end if;
 eid:=ecb8.event(s,a,h,'authorize',req||jsonb_build_object('tick',h->'tick'),request);
 return jsonb_build_object('event',eid,'replayed',false);
end $function$

CREATE OR REPLACE FUNCTION ecb8.conditions(h jsonb, envelope uuid, stage text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare gaps jsonb:='[]'; r record; cur uuid; c jsonb; begin
 c:=ecb8.doc(envelope,'b8_envelope');
 -- Exact immutable closure and finite semantics are revalidated at every use.
 if ecb8.examine(envelope,(c->>'contract')::uuid)->>'outcome' is distinct from 'PASS' then gaps:=gaps||'"qualification_or_integrity"'::jsonb; end if;
 select current_event into cur from ecb7.scopes where id=(c->>'scope')::uuid;
 if cur::text is distinct from c->'orientation'->>'designation' then gaps:=gaps||'"orientation_selection"'::jsonb; end if;
 for r in select * from jsonb_each(c->'dependencies') loop
  if h->'dependencies'->r.key is distinct from r.value->'revision' then gaps:=gaps||jsonb_build_array('dependency:'||r.key); end if;
 end loop;
 if stage in ('admit','effect','start') and (h->'value' is distinct from c->'from_value' or h->'revision' is distinct from c->'target_revision'
 or h->'ready' is distinct from 'true'::jsonb) then gaps:=gaps||'"target_state"'::jsonb; end if;
 if (stage='authorize' and ((h->>'tick')::int<10 or (h->>'tick')::int>=12))
 or (stage='admit' and ((h->>'tick')::int<10 or (h->>'tick')::int>=20))
 or (stage in ('start','effect') and (h->>'tick')::int>=30) then gaps:=gaps||jsonb_build_array('temporal:'||stage); end if;
 return gaps;
end $function$

CREATE OR REPLACE FUNCTION ecb8.control(s uuid, a uuid, operation text, subject uuid, p uuid, request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare h jsonb; au jsonb; ad jsonb; st jsonb; c jsonb; prior jsonb; eid uuid; d jsonb; begin
 if operation not in ('admit','start','effect','reconcile') then raise exception 'b8_bounded_operation'; end if;
 perform ecb8.lock_scope(s); h:=ecb8.history(s,a);
 if h->'initial'->>'actor_login' is distinct from session_user then raise exception 'b8_authenticated_actor'; end if;
 -- Exact transport replays are observational, including expired/stale historical calls.
 select x into prior from jsonb_array_elements(h->'events') x where x->>'request'=request::text;
 if prior is not null then
  if prior->>'login'<>session_user or prior->>'predecessor' is distinct from p::text
  or prior->>'kind' is distinct from (case when operation='reconcile' then 'fence' else operation end)
  or (case operation when 'admit' then prior->'data'->>'authorization' when 'start' then prior->'data'->>'admission'
       else prior->'data'->>'start' end) is distinct from subject::text then raise exception 'b8_request_conflict'; end if;
  return jsonb_build_object('event',prior->'id','replayed',true,'effect_count',jsonb_array_length(h->'effects'),'retry','HOLD');
 end if;
 -- Inspect committed competitor state before predecessor check: E5 waiter proof.
 if jsonb_array_length(h->'effects')>0 then raise exception 'b8_effect_allowance_consumed'; end if;
 perform ecb8.expected(h,p);
 if operation='reconcile' then
  if not(h->'starts' ? subject::text) or h->'terminals' ? subject::text then raise exception 'b8_start_terminal_or_missing'; end if;
  eid:=ecb8.event(s,a,h,'fence',jsonb_build_object('start',subject,'reason','complete_serialized_no_native_effect'),request);
  return jsonb_build_object('event',eid,'effect_count',0,'disposition','FENCED_FRESH_ADMISSION_REQUIRED');
 end if;
 au:=h->'selected';
 if au is null or au='null'::jsonb then raise exception 'b8_selected_authorization_required'; end if;
 if h->'revoked_grants' ? (au->>'grant') or h->'revoked_authorizations' ? (au->>'id') then raise exception 'b8_revoked'; end if;
 c:=ecb8.doc((au->>'envelope')::uuid,'b8_envelope');
 if c->>'actor' is distinct from h->'initial'->'principals'->>session_user then raise exception 'b8_actor_binding'; end if;
 if ecb8.conditions(h,(au->>'envelope')::uuid,operation)<>'[]'::jsonb then raise exception 'b8_conditions:%',ecb8.conditions(h,(au->>'envelope')::uuid,operation); end if;
 if operation='admit' then
  if au->>'id' is distinct from subject::text then raise exception 'b8_authorization_subject'; end if;
  if exists(select 1 from jsonb_each(h->'starts') x where not(h->'terminals' ? x.key)) then raise exception 'b8_reconcile_required'; end if;
  d:=au-'id'||jsonb_build_object('authorization',subject,'observation',ecb8.observation(h));
 elsif operation='start' then
  ad:=h->'admissions'->subject::text;
  if ad is null or ad->>'authorization' is distinct from au->>'id' then raise exception 'b8_admission_binding'; end if;
  if ad->>'xid'=pg_current_xact_id()::text then raise exception 'b8_committed_admission_required'; end if;
  if exists(select 1 from jsonb_each(h->'starts') x where not(h->'terminals' ? x.key) or x.value->>'admission'=subject::text) then raise exception 'b8_admission_used_or_unresolved'; end if;
  d:=jsonb_build_object('admission',subject);
 else
  st:=h->'starts'->subject::text; ad:=h->'admissions'->(st->>'admission');
  if st is null or h->'terminals' ? subject::text then raise exception 'b8_start_terminal_or_missing'; end if;
  if st->>'xid'=pg_current_xact_id()::text then raise exception 'b8_committed_start_required'; end if;
  if ad->>'authorization' is distinct from au->>'id' then raise exception 'b8_selected_envelope_changed'; end if;
  d:=jsonb_build_object('start',subject,'target',c->'target','operation','advance_one','delta',1,'observation',ecb8.observation(h));
 end if;
 eid:=ecb8.event(s,a,h,operation,d,request);
 return jsonb_build_object('event',eid,'replayed',false,'effect_count',case when operation='effect' then 1 else 0 end);
end $function$

CREATE OR REPLACE FUNCTION ecb8.doc(i uuid, expected_role text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare r public.artifacts; begin
 select * into strict r from public.artifacts where id=i;
 if expected_role is not null and r.artifact_role<>expected_role then raise exception 'b8_wrong_role:%',i; end if;
 if r.payload_text is null or r.payload_digest<>extensions.digest(convert_to(r.payload_text,'UTF8'),'sha256')
 or not(r.payload_text is json object with unique keys) then raise exception 'b8_payload_integrity:%',i; end if;
 return r.payload_text::jsonb;
end $function$

CREATE OR REPLACE FUNCTION ecb8.event(s uuid, a uuid, h jsonb, k text, d jsonb, request uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ begin
 if h->'initial'->'principals'->>session_user is null then raise exception 'b8_authenticated_participant_required'; end if;
 return ecb8.retain('b8_event',s,jsonb_build_object('scope',s,'action',a,'kind',k,'predecessor',h->'head',
 'login',session_user,'participant',h->'initial'->'principals'->session_user,'request',request,'data',d)::text);
end $function$

CREATE OR REPLACE FUNCTION ecb8.examine(envelope uuid, contract uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c jsonb; ct jsonb; init jsonb; deps jsonb; d jsonb; f jsonb:='[]'; failures jsonb:='[]'; gaps jsonb:='[]';
 r record; q jsonb; keydoc jsonb; designation jsonb; src jsonb; meaning jsonb; expected_meaning jsonb;
 outcome text; status text; required text[]; actual text[]; observed jsonb; begin
 c:=ecb8.doc(envelope,'b8_envelope'); ct:=ecb8.doc(contract,'b8_basis');
 init:=ecb8.initial((ct->>'scope')::uuid,(ct->>'action')::uuid);
 if ct->>'kind'<>'contract' then raise exception 'b8_comparison_contract_required'; end if;
 status:='PASS';
 if c->>'contract' is distinct from contract::text or c->>'method' is distinct from ct->>'method'
 or ct->>'method'<>encode(extensions.digest(convert_to(pg_get_functiondef('ecb8.examine(uuid,uuid)'::regprocedure),'UTF8'),'sha256'),'hex')
 or c->>'scope' is distinct from ct->>'scope' or c->>'action' is distinct from ct->>'action'
 or c->>'target' is distinct from init->>'target' or c->>'actor' is distinct from init->>'actor'
 or c->'orientation' is distinct from ct->'orientation' then status:='FAIL'; end if;
 f:=f||jsonb_build_array(jsonb_build_object('obligation','exact_binding','status',status,'witness',c-'expression'));
 deps:=c->'dependencies';
 select array_agg(x order by x) into required from (select jsonb_object_keys(ct->'required') x union select contract::text) t;
 select array_agg(x order by x) into actual from jsonb_object_keys(deps) x;
 if required is distinct from actual then gaps:=gaps||jsonb_build_array('required_manifest_members'); end if;
 for r in select * from jsonb_each(ct->'required'||jsonb_build_object(contract::text,jsonb_build_object('role','b8_basis'))) loop
  if not(deps ? r.key) then continue; end if;
  begin
   d:=ecb8.doc(r.key::uuid,r.value->>'role');
   if deps->r.key->>'role' is distinct from r.value->>'role'
    or deps->r.key->>'digest' is distinct from (select encode(payload_digest,'hex') from public.artifacts where public.artifacts.id=r.key::uuid)
    or deps->r.key->>'revision' is distinct from '1' then failures:=failures||jsonb_build_array(r.key); end if;
  exception when others then gaps:=gaps||jsonb_build_array(jsonb_build_object('id',r.key,'gap',sqlerrm)); end;
 end loop;
 status:=case when jsonb_array_length(failures)>0 then 'FAIL' when jsonb_array_length(gaps)>0 then 'INCOMPLETE' else 'PASS' end;
 f:=f||jsonb_build_array(jsonb_build_object('obligation','closure','status',status,'witness',jsonb_build_object('mismatches',failures,'gaps',gaps)));
 status:='PASS';
 if c->>'operation' is distinct from 'advance_one' or c->'delta' is distinct from '1'::jsonb
 or c->'max_effects' is distinct from '1'::jsonb or c->'from_value' is distinct from '0'::jsonb
 or c->'target_revision' is distinct from '0'::jsonb or c->'ready' is distinct from 'true'::jsonb
 or c->>'observation_access' is distinct from 'external' then status:='FAIL'; end if;
 f:=f||jsonb_build_array(jsonb_build_object('obligation','action_meaning','status',status,'witness',jsonb_build_object('delta',c->'delta','maximum',c->'max_effects','access',c->'observation_access')));
 status:='PASS';
 if c->'temporal' is distinct from '{"issue":[10,12],"admit":[10,20],"effect_before":30,"unrevoked_through_effect":true}'::jsonb
 or c->>'retry' is distinct from 'observe_then_explicit_fence_before_fresh_admission' then status:='FAIL'; end if;
 f:=f||jsonb_build_array(jsonb_build_object('obligation','temporal_retry','status',status,'witness',jsonb_build_object('temporal',c->'temporal','retry',c->'retry')));
 expected_meaning:=jsonb_build_object('target',init->'target','action',ct->'action','from_value',0,'revision',0,'delta',1,'maximum',1,'access','external');
 meaning:=ct->'interpretations'->(c->>'expression');
 status:=case when meaning is null then 'INCOMPLETE' when meaning='null'::jsonb then 'INDETERMINATE'
 when meaning is distinct from expected_meaning then 'FAIL' else 'PASS' end;
 f:=f||jsonb_build_array(jsonb_build_object('obligation','expression_meaning','status',status,'witness',jsonb_build_object('expression',c->'expression','interpreted',meaning,'required',expected_meaning)));
 status:='PASS';
 begin
  keydoc:=ecb8.doc((ct->'orientation'->>'key')::uuid,'b7_candidate');
  q:=ecb8.doc((ct->'orientation'->>'evaluation')::uuid,'b7_evaluation');
  designation:=ecb8.doc((ct->'orientation'->>'designation')::uuid,'b7_designation');
  if q->>'outcome'<>'PASS' or q->'basis' is distinct from keydoc or q->>'candidate' is distinct from ct->'orientation'->>'key'
  or designation->>'candidate' is distinct from ct->'orientation'->>'key' or designation->>'evaluation' is distinct from ct->'orientation'->>'evaluation'
  or designation->>'operation'<>'select' or designation->>'scope' is distinct from ct->>'scope'
  or not(keydoc->'conclusions' @> '[{"comparison":"native","answer":false},{"comparison":"external","answer":true}]') then status:='FAIL'; end if;
  -- Explicit source observations and latency/access remain independently retained.
  for r in select * from jsonb_each(ct->'required') where value ? 'access' loop
   src:=ecb8.doc(r.key::uuid,'b7_snapshot');
   if r.value->>'access'='native' and src->'observations' is distinct from '[20,20]'::jsonb then status:='FAIL'; end if;
   if r.value->>'access'='external' and (src->'observations' is distinct from '[20.1,20.2]'::jsonb or (src->>'latency')::numeric>60) then status:='FAIL'; end if;
  end loop;
 exception when others then status:='INCOMPLETE'; end;
 f:=f||jsonb_build_array(jsonb_build_object('obligation','orientation_grounding','status',status,'witness',ct->'orientation'));
 observed:=ecb8.history((ct->>'scope')::uuid,(ct->>'action')::uuid); status:='PASS';
 if (select current_event::text from ecb7.scopes where id=(ct->>'scope')::uuid) is distinct from ct->'orientation'->>'designation' then status:='FAIL'; end if;
 for r in select * from jsonb_each(deps) loop
  if observed->'dependencies'->r.key is distinct from r.value->'revision' then status:='FAIL'; end if;
 end loop;
 f:=f||jsonb_build_array(jsonb_build_object('obligation','declared_current_basis','status',status,'witness',observed->'dependencies'));
 if exists(select 1 from jsonb_array_elements(f) x where x->>'status'='FAIL') then outcome:='FAIL';
 elsif exists(select 1 from jsonb_array_elements(f) x where x->>'status'='INCOMPLETE') then outcome:='INCOMPLETE';
 elsif exists(select 1 from jsonb_array_elements(f) x where x->>'status'='INDETERMINATE') then outcome:='INDETERMINATE'; else outcome:='PASS'; end if;
 return jsonb_build_object('outcome',outcome,'findings',f,'method',ct->'method','envelope',envelope,'contract',contract,
 'scope',ct->'scope','action',ct->'action','meaning','eligibility_only','limits',ct->'limits');
end $function$

CREATE OR REPLACE FUNCTION ecb8.fixture(s uuid, a uuid, j jsonb, p uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare h jsonb; k text; ref_id uuid; c jsonb; begin
 perform ecb8.lock_scope(s); k:=j->>'kind';
 if j->>'scope' is distinct from s::text or j->>'action' is distinct from a::text or j->'synthetic' is distinct from 'true'::jsonb then raise exception 'b8_synthetic_fixture_only'; end if;
 if k='target_initial' then
  perform ecb8.keys(j,array['kind','scope','action','synthetic','target','actor','actor_login','principals','dependencies']);
  if exists(select 1 from public.artifacts where artifact_role='b8_basis' and context_id=s and payload_text::jsonb->>'kind'='target_initial') then raise exception 'b8_one_action_target'; end if;
  for ref_id in select value::uuid from jsonb_each_text(j->'principals') union select a union select (j->>'target')::uuid loop
   if not exists(select 1 from public.referents where public.referents.id=ref_id) then raise exception 'b8_referent_required'; end if;
  end loop;
  if j->'principals'->>(j->>'actor_login') is distinct from j->>'actor' then raise exception 'b8_authentication_basis'; end if;
 else
  h:=ecb8.history(s,a); perform ecb8.expected(h,p);
  if k='contract' then
   perform ecb8.keys(j,array['kind','scope','action','synthetic','target','actor','initial','orientation','required','interpretations','method','method_definition','limits']);
   if j->>'method'<>encode(extensions.digest(convert_to(pg_get_functiondef('ecb8.examine(uuid,uuid)'::regprocedure),'UTF8'),'sha256'),'hex')
   or j->>'method_definition'<>pg_get_functiondef('ecb8.examine(uuid,uuid)'::regprocedure) then raise exception 'b8_method_binding'; end if;
  elsif k='grant' then
   perform ecb8.keys(j,array['kind','scope','action','synthetic','issuer','actor','login','target','operation','envelope','evaluation','predecessor','temporal','rights']);
   if j->>'issuer'<>'A_TEST' then raise exception 'b8_fixture_issuer'; end if;
  else raise exception 'b8_basis_subtype'; end if;
 end if;
 return ecb8.retain('b8_basis',s,j::text);
end $function$

CREATE OR REPLACE FUNCTION ecb8.history(s uuid, a uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare init jsonb; rows jsonb; ev jsonb; data jsonb; h jsonb; nexts jsonb; eid text;
 head text; seen text[]:='{}'; n int; k text; st jsonb; ad jsonb; au jsonb; c jsonb; g jsonb;
 legal boolean; r record; begin
 init:=ecb8.initial(s,a);
 h:=jsonb_build_object('head',null,'initial',init,'value',0,'revision',0,'ready',true,'tick',10,
 'selected',null,'selection_head',null,'revoked_grants','[]'::jsonb,'revoked_authorizations','[]'::jsonb,
 'dependencies',init->'dependencies','admissions','{}'::jsonb,'starts','{}'::jsonb,'terminals','{}'::jsonb,
 'effects','[]'::jsonb,'acks','[]'::jsonb,'events','[]'::jsonb,'legitimate',true);
 rows:='[]';
 -- Include context/declared-scope discrepancies so they cannot disappear from observation.
 for r in select * from public.artifacts where artifact_role='b8_event'
 and (context_id=s or payload_text::jsonb->>'scope'=s::text)
 and payload_text::jsonb->>'action'=a::text loop
  ev:=ecb8.doc(r.id,'b8_event');
  if r.context_id<>s or ev->>'scope' is distinct from s::text then raise exception 'b8_scope_mismatch'; end if;
  perform ecb8.keys(ev,array['scope','action','kind','predecessor','login','participant','request','data']);
  rows:=rows||jsonb_build_array(ev||jsonb_build_object('id',r.id,'xid',r.created_xid::text));
 end loop;
 n:=jsonb_array_length(rows);
 while cardinality(seen)<n loop
  select coalesce(jsonb_agg(x),'[]') into nexts from jsonb_array_elements(rows) x where x->>'predecessor' is not distinct from head;
  if jsonb_array_length(nexts)<>1 then raise exception 'b8_broken_fork_cycle_history'; end if;
  ev:=nexts->0; eid:=ev->>'id';
  if eid=any(seen) then raise exception 'b8_cycle'; end if;
  seen:=array_append(seen,eid); k:=ev->>'kind'; data:=ev->'data';
  if ev->>'participant' is distinct from init->'principals'->> (ev->>'login') then raise exception 'b8_participant_binding'; end if;
  if exists(select 1 from jsonb_array_elements(h->'events') x where x->>'request'=ev->>'request') then raise exception 'b8_request_fork'; end if;
  case k
   when 'tick' then
    perform ecb8.keys(data,array['tick']);
    if jsonb_typeof(data->'tick') is distinct from 'number' then raise exception 'b8_integer_tick_required'; end if;
    if (data->>'tick')::int <= (h->>'tick')::int then raise exception 'b8_tick_not_increasing'; end if;
    h:=h||jsonb_build_object('tick',data->'tick');
   when 'ready' then
    perform ecb8.keys(data,array['ready']);
    if jsonb_typeof(data->'ready')<>'boolean' or data->'ready'=h->'ready' then raise exception 'b8_native_change_required'; end if;
    h:=h||jsonb_build_object('ready',data->'ready','revision',(h->>'revision')::int+1);
   when 'dependency' then
    perform ecb8.keys(data,array['source','revision']);
    if data->>'revision' is null or data->'revision'=h->'dependencies'->(data->>'source') then raise exception 'b8_revision_change_required'; end if;
    h:=jsonb_set(h,array['dependencies',data->>'source'],data->'revision');
   when 'revoke_grant' then
    perform ecb8.keys(data,array['grant']); perform ecb8.doc((data->>'grant')::uuid,'b8_basis');
    h:=h||jsonb_build_object('revoked_grants',h->'revoked_grants'||jsonb_build_array(data->'grant'));
   when 'withdraw' then
    perform ecb8.keys(data,array['authorization']);
    if data->>'authorization' is distinct from h->'selected'->>'id' then raise exception 'b8_withdraw_binding'; end if;
    h:=h||jsonb_build_object('revoked_authorizations',h->'revoked_authorizations'||jsonb_build_array(data->'authorization'),
       'selected',null,'selection_head',eid);
   when 'authorize' then
    perform ecb8.keys(data,array['authorization','designation','tick']);
    au:=data->'authorization'; perform ecb8.keys(au,array['envelope','evaluation','grant']);
    perform ecb8.keys(data->'designation',array['envelope','predecessor']);
    if data->'designation'->>'predecessor' is distinct from h->>'selection_head'
    or data->'designation'->'envelope' is distinct from au->'envelope' then raise exception 'b8_designation_binding'; end if;
    h:=h||jsonb_build_object('selected',au||jsonb_build_object('id',eid),'selection_head',eid);
   when 'admit' then
    perform ecb8.keys(data,array['authorization','envelope','evaluation','grant','observation']);
    h:=jsonb_set(h,array['admissions',eid],data||jsonb_build_object('id',eid,'xid',ev->'xid'));
   when 'start' then
    perform ecb8.keys(data,array['admission']);
    if not(h->'admissions' ? (data->>'admission')) then raise exception 'b8_missing_admission'; end if;
    if exists(select 1 from jsonb_each(h->'starts') x where x.value->>'admission'=data->>'admission'
      or not(h->'terminals' ? x.key)) then raise exception 'b8_conflicting_start'; end if;
    h:=jsonb_set(h,array['starts',eid],data||jsonb_build_object('id',eid,'xid',ev->'xid'));
   when 'fence' then
    perform ecb8.keys(data,array['start','reason']);
    if not(h->'starts' ? (data->>'start')) or h->'terminals' ? (data->>'start') or jsonb_array_length(h->'effects')>0 then raise exception 'b8_conflicting_terminal'; end if;
    h:=jsonb_set(h,array['terminals',data->>'start'],ev);
   when 'effect' then
    perform ecb8.keys(data,array['start','target','operation','delta','observation']);
    if data->>'target' is distinct from init->>'target' or data->>'operation'<>'advance_one' or data->'delta'<>'1'::jsonb then raise exception 'b8_native_history_gap'; end if;
    if h->'terminals' ? (data->>'start') then raise exception 'b8_conflicting_terminal'; end if;
    st:=h->'starts'->(data->>'start'); ad:=h->'admissions'->(st->>'admission'); au:=h->'selected';
    legal:=false;
    if st is not null and ad is not null and au is not null then
     c:=ecb8.doc((ad->>'envelope')::uuid,'b8_envelope'); g:=ecb8.doc((ad->>'grant')::uuid,'b8_basis');
     legal:=ad->>'authorization'=au->>'id' and c->>'actor'=ev->>'participant'
      and g->>'login'=ev->>'login' and not(h->'revoked_grants' ? (ad->>'grant'))
      and not(h->'revoked_authorizations' ? (ad->>'authorization'))
      and c->'from_value'=h->'value' and c->'target_revision'=h->'revision' and h->'ready'='true'::jsonb
      and (h->>'tick')::int<30 and jsonb_array_length(h->'effects')=0
      and data->'observation'->'value'=h->'value' and data->'observation'->'revision'=h->'revision'
      and data->'observation'->'tick'=h->'tick'
      and data->'observation'->'orientation'=c->'orientation'->'designation';
     for r in select key,value from jsonb_each(c->'dependencies') loop
      legal:=legal and r.value->'revision'=h->'dependencies'->r.key;
     end loop;
    end if;
    h:=h||jsonb_build_object('value',(h->>'value')::int+1,'revision',(h->>'revision')::int+1,
     'effects',h->'effects'||jsonb_build_array(ev||jsonb_build_object('legitimate',coalesce(legal,false))),
     'legitimate',(h->>'legitimate')::boolean and coalesce(legal,false));
    if st is not null then h:=jsonb_set(h,array['terminals',data->>'start'],ev); end if;
   when 'ack' then
    perform ecb8.keys(data,array['start','reported_terminal','received']);
    h:=h||jsonb_build_object('acks',h->'acks'||jsonb_build_array(ev));
   else raise exception 'b8_unknown_event_subtype';
  end case;
  h:=h||jsonb_build_object('events',h->'events'||jsonb_build_array(ev),'head',eid); head:=eid;
 end loop;
 return h;
end $function$

CREATE OR REPLACE FUNCTION ecb8.initial(s uuid, a uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare ids uuid[]; j jsonb; begin
 select array_agg(id) into ids from public.artifacts where artifact_role='b8_basis'
 and context_id=s and payload_text::jsonb->>'action'=a::text and payload_text::jsonb->>'kind'='target_initial';
 if coalesce(cardinality(ids),0)<>1 then raise exception 'b8_exact_initial_required'; end if;
 j:=ecb8.doc(ids[1],'b8_basis');
 if j->>'scope' is distinct from s::text then raise exception 'b8_scope_mismatch'; end if;
 return j||jsonb_build_object('id',ids[1]);
end $function$

CREATE OR REPLACE FUNCTION ecb8.inspect(s uuid, a uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare h jsonb; disposition text; retained jsonb; r record; begin
 begin perform ecb8.lock_scope(s,true);
 exception when lock_not_available then return jsonb_build_object('status','UNKNOWN / IN_FLIGHT','retry','HOLD','fence',null,'observation_bound','one NOWAIT scope-lock attempt'); end;
 begin
  h:=ecb8.history(s,a);
  if jsonb_array_length(h->'effects')>0 then disposition:='EFFECT_ESTABLISHED';
  elsif exists(select 1 from jsonb_each(h->'starts') x where not(h->'terminals' ? x.key)) then disposition:='RECONCILE_REQUIRED';
  else disposition:='NO_EFFECT_ESTABLISHED'; end if;
  -- Return exact retained bytes over the declared bounded read surface. The
  -- fresh-process reader independently hashes and follows the exact closure.
  select coalesce(jsonb_agg(jsonb_build_object('id',id,'role',artifact_role,'context',context_id,'bytes',payload_text,
    'digest',encode(payload_digest,'hex'),'xid',created_xid::text)),'[]') into retained
    from public.artifacts where (artifact_role like 'b8_%' and context_id=s) or id in (
     select dep.key::uuid from public.artifacts ct cross join lateral jsonb_each(ct.payload_text::jsonb->'required') dep
     where ct.artifact_role='b8_basis' and ct.context_id=s and ct.payload_text::jsonb->>'kind'='contract');
  return jsonb_build_object('status',disposition,'retry',case when disposition='NO_EFFECT_ESTABLISHED' then 'FRESH_ADMISSION_REQUIRED' else 'HOLD' end,
   'history',h,'retained',retained,'current_orientation',(select current_event from ecb7.scopes where id=s),'boundary','complete bounded history under exact shared scope lock',
   'proof_class','atomic-ledger synthetic target only');
 exception when others then return jsonb_build_object('status','UNKNOWN','retry','HOLD','reason',sqlerrm); end;
end $function$

CREATE OR REPLACE FUNCTION ecb8.lock_scope(s uuid, observation boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ begin
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'b8_read_committed_required'; end if;
 if observation then
  perform id from ecb7.scopes where id=s and synthetic for update nowait;
 else
  perform id from ecb7.scopes where id=s and synthetic for update;
 end if;
 if not found then raise exception 'b8_synthetic_scope_required'; end if;
end $function$

CREATE OR REPLACE FUNCTION ecb8.prepare_artifact()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare j jsonb; begin
 if new.payload_digest is not null or new.recorded_at is not null or new.created_xid is not null then
  raise exception 'b8_derived_columns'; end if;
 if new.payload_text is null or not(new.payload_text is json object with unique keys) then
  raise exception 'b8_exact_unique_json_required'; end if;
 j:=new.payload_text::jsonb;
 if current_user<>'ecb8_owner' then raise exception 'b8_protected_publication'; end if;
 if j->>'scope' is null or j->>'action' is null then raise exception 'b8_exact_locator_required'; end if;
 if exists(select 1 from public.referents where id=new.id) then raise exception 'b8_identity_already_registered'; end if;
 insert into public.referents(id) values(new.id);
 new.payload_digest:=extensions.digest(convert_to(new.payload_text,'UTF8'),'sha256');
 new.recorded_at:=transaction_timestamp(); new.created_xid:=pg_current_xact_id();
 return new;
end $function$

CREATE OR REPLACE FUNCTION ecb8.propose(s uuid, a uuid, bytes text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare h jsonb; c jsonb; begin
 perform ecb8.lock_scope(s); h:=ecb8.history(s,a);
 if not(bytes is json object with unique keys) then raise exception 'b8_exact_unique_json_required'; end if;
 c:=bytes::jsonb;
 perform ecb8.keys(c,array['scope','action','target','actor','operation','from_value','target_revision','ready','delta','max_effects',
 'orientation','dependencies','method','contract','expression','observation_access','temporal','retry']);
 if c->>'scope' is distinct from s::text or c->>'action' is distinct from a::text then raise exception 'b8_locator_binding'; end if;
 -- Wrong meanings/values remain retainable; qualification must discriminate them.
 return ecb8.retain('b8_envelope',s,bytes);
end $function$

CREATE OR REPLACE FUNCTION ecb8.qualify(s uuid, a uuid, envelope uuid, contract uuid, p uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare h jsonb; q jsonb; begin
 perform ecb8.lock_scope(s); h:=ecb8.history(s,a); perform ecb8.expected(h,p);
 q:=ecb8.examine(envelope,contract);
 if q->>'scope' is distinct from s::text or q->>'action' is distinct from a::text then raise exception 'b8_qualification_locator'; end if;
 return ecb8.retain('b8_evaluation',s,(q||jsonb_build_object('evaluator',session_user))::text);
end $function$

CREATE OR REPLACE FUNCTION ecb_governance.check_session(scope_id uuid, secret text, csrf text, mutation boolean)
 RETURNS ecb_governance.sessions
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare s ecb_governance.sessions; begin
 select * into s from ecb_governance.sessions where scope=scope_id and secret_hash=ecb_governance.hash(secret) for update;
 if not found or s.invalidated_at is not null or s.absolute_expires<=clock_timestamp() or s.last_active+interval '24 hours'<=clock_timestamp() then raise exception 'session_required'; end if;
 if mutation then
 if csrf is null or s.csrf_hash<>ecb_governance.hash(csrf) then raise exception 'csrf_rejected'; end if;
 update ecb_governance.sessions set last_active=clock_timestamp() where id=s.id;
 end if;
 return s;
end $function$

CREATE OR REPLACE FUNCTION ecb_governance.commission(p0_bytes text, remit_bytes text, basis_bytes text, source_ref text, setup_digest text, expected_keys integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r uuid; p uuid; m uuid; b uuid; h_id uuid; existing ecb_governance.scopes; begin
 -- Serialize setup retries on the opaque capability digest before retaining new subjects.
 perform pg_advisory_xact_lock(hashtextextended(setup_digest,0));
 select * into existing from ecb_governance.scopes where setup_hash=setup_digest;
 if found then
 if existing.credential_count is distinct from expected_keys
 or (select payload from ecb_governance.subjects where id=existing.p0) is distinct from p0_bytes
 or (select payload from ecb_governance.subjects where id=existing.remit) is distinct from remit_bytes
 or (select payload from ecb_governance.subjects where id=existing.root_basis) is distinct from basis_bytes
 or (select source from ecb_governance.subjects where id=existing.root_basis) is distinct from source_ref then raise exception 'request_conflict'; end if;
 return existing.id;
 end if;
 if ecb_governance.hash(p0_bytes)<>'686148f540860aca57a43d8cdf02ee15a0f6314d14b54736e6baf6f1846a7664' then raise exception 'wrong_p0'; end if;
 p:=ecb_governance.retain('policy',p0_bytes,source_ref); m:=ecb_governance.retain('remit',remit_bytes,source_ref);
 b:=ecb_governance.retain('external_basis',basis_bytes,source_ref); h_id:=ecb_governance.identity();
 insert into ecb_governance.scopes(h,remit,root_basis,p0,rp_id,origin,user_handle,setup_hash,setup_expires,credential_count)
 values(h_id,m,b,p,'ecos.effortlessconnection.com','https://ecos.effortlessconnection.com',replace(gen_random_uuid()::text,'-',''),setup_digest,clock_timestamp()+interval '30 minutes',expected_keys) returning id into r;
 return r;
end $function$

CREATE OR REPLACE FUNCTION ecb_governance.executor(action text, a jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s ecb_governance.scopes; d ecb_governance.decisions; t ecb_governance.transitions; r uuid; fp text; obligations jsonb;
begin
 select * into s from ecb_governance.scopes where id=(a->>'scope')::uuid for update;
 if not found then raise exception 'unknown_scope'; end if;
 if action='inspect' then return ecb_governance.view_scope(s.id); end if;
 if action not in ('execute','recover') then raise exception 'unsupported_operation'; end if;
 fp:=ecb_governance.hash(a::text);
 select * into t from ecb_governance.transitions where scope=s.id and request_id=(a->>'request_id')::uuid;
 if found then if t.fingerprint<>fp then raise exception 'request_conflict'; end if; return jsonb_build_object('outcome','committed','transition',to_jsonb(t)); end if;
 if (select count(*) from ecb_governance.transitions where scope=s.id and not exists(select 1 from ecb_governance.transitions child where child.predecessor=ecb_governance.transitions.id))<>(case when s.current_transition is null then 0 else 1 end)
 or (s.current_transition is not null and exists(select 1 from ecb_governance.transitions where predecessor=s.current_transition)) then raise exception 'inconsistent_history'; end if;
 if s.current_transition is not null and not exists(select 1 from ecb_governance.transitions where id=s.current_transition and h=s.h and remit=s.remit and binding=s.binding) then raise exception 'inconsistent_binding'; end if;
 if action='recover' then return jsonb_build_object('outcome','not_committed','current_transition',s.current_transition,'scope_locked',true); end if;
 select * into d from ecb_governance.decisions where id=(a->>'decision')::uuid and scope=s.id;
 if not found or d.operation not in ('genesis','succession') then raise exception 'authorization_required'; end if;
 if d.created_xid=pg_current_xact_id() then raise exception 'prior_commit_required'; end if;
 if exists(select 1 from ecb_governance.transitions where decision=d.id) then raise exception 'decision_consumed'; end if;
 if d.predecessor is distinct from s.current_transition or d.predecessor is distinct from (a->>'predecessor')::uuid then raise exception 'stale_predecessor'; end if;
 if s.binding is null or d.h<>s.h then raise exception 'binding_required'; end if;
 if (select digest from ecb_governance.subjects where id=d.policy) is distinct from a->>'policy_digest' then raise exception 'wrong_digest'; end if;
 perform ecb_governance.policy((select payload from ecb_governance.subjects where id=d.policy));
 if exists(select 1 from ecb_governance.decisions where target=d.id and operation='withdraw') then raise exception 'decision_withdrawn'; end if;
 if d.operation='genesis' then
 if s.current_transition is not null or d.policy<>s.p0 or d.basis<>s.root_basis then raise exception 'bootstrap_exhausted'; end if;
 obligations:='["activate_exact_p0","designate_initial_h_and_remit","exhaust_bootstrap"]';
 else
 if s.current_transition is null or d.basis<>s.current_transition then raise exception 'wrong_authority_basis'; end if;
 obligations:='["install_exact_successor","preserve_h_remit_history_and_exhaustion"]';
 end if;
 insert into ecb_governance.transitions(scope,predecessor,decision,policy,h,remit,binding,obligations,executor,request_id,fingerprint)
 values(s.id,d.predecessor,d.id,d.policy,s.h,s.remit,s.binding,obligations,session_user,(a->>'request_id')::uuid,fp) returning id into r;
 update ecb_governance.scopes set current_transition=r where id=s.id;
 return jsonb_build_object('outcome','committed','transition',(select to_jsonb(x) from ecb_governance.transitions x where id=r));
end $function$

CREATE OR REPLACE FUNCTION ecb_governance.human(action text, a jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s ecb_governance.scopes; c ecb_governance.ceremonies; k ecb_governance.credentials;
 ss ecb_governance.sessions; d ecb_governance.decisions; prior ecb_governance.transitions;
 r uuid; p uuid; b uuid; fp text; keys jsonb; cp jsonb;
begin
 select * into s from ecb_governance.scopes where id=(a->>'scope')::uuid for update;
 if not found then raise exception 'unknown_scope'; end if;
 if action in ('setup_view','registration_options','registration_finish','bind') then perform ecb_governance.check_setup(s,a->>'setup_secret'); end if;
 if action='setup_view' then
 return ecb_governance.view_scope(s.id);
 elsif action in ('registration_options','authentication_options') then
 if action='authentication_options' and s.binding is null then raise exception 'unbound_identity'; end if;
 if action='registration_options' and (select count(*) from ecb_governance.credentials where scope=s.id)>=s.credential_count then raise exception 'enrollment_complete'; end if;
 if (select count(*) from ecb_governance.ceremonies where scope=s.id and expires>clock_timestamp() and consumed_at is null)>=20 then raise exception 'ceremony_limit'; end if;
 insert into ecb_governance.ceremonies(scope,purpose,challenge,browser_hash)
 values(s.id,case action when 'registration_options' then 'registration' else 'authentication' end,a->>'challenge',a->>'browser_hash') returning id into r;
 return jsonb_build_object('ceremony',r,'user_handle',s.user_handle,'credentials',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from ecb_governance.credentials x where scope=s.id));
 elsif action='ceremony' then
 select * into c from ecb_governance.ceremonies where id=(a->>'ceremony')::uuid and scope=s.id;
 if not found or c.consumed_at is not null or c.expires<=clock_timestamp() or c.browser_hash is distinct from a->>'browser_hash' then raise exception 'ceremony_unavailable'; end if;
 return jsonb_build_object('ceremony',to_jsonb(c),'user_handle',s.user_handle,'credentials',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from ecb_governance.credentials x where scope=s.id));
 elsif action in ('registration_finish','authentication_finish') then
 select * into c from ecb_governance.ceremonies where id=(a->>'ceremony')::uuid and scope=s.id for update;
 if not found or c.consumed_at is not null or c.expires<=clock_timestamp() or c.browser_hash is distinct from a->>'browser_hash'
 or c.purpose is distinct from (case action when 'registration_finish' then 'registration' else 'authentication' end) then raise exception 'ceremony_unavailable'; end if;
 if jsonb_typeof(a->'proof') is distinct from 'object' then raise exception 'proof_required'; end if;
 if action='registration_finish' then
 if (select count(*) from ecb_governance.credentials where scope=s.id)>=s.credential_count then raise exception 'enrollment_complete'; end if;
 insert into ecb_governance.credentials(scope,credential_id,public_key,counter,transports,device_type,backed_up,enrollment_ceremony)
 values(s.id,a->>'credential_id',a->>'public_key',(a->>'counter')::bigint,a->'transports',a->>'device_type',(a->>'backed_up')::boolean,c.id) returning id into r;
 else
 if s.binding is null then raise exception 'unbound_identity'; end if;
 select * into k from ecb_governance.credentials where scope=s.id and credential_id=a->>'credential_id' for update;
 if not found or k.counter<>(a->>'old_counter')::bigint or ((k.counter>0 or (a->>'counter')::bigint>0) and (a->>'counter')::bigint<=k.counter) then raise exception 'credential_changed'; end if;
 update ecb_governance.credentials set counter=(a->>'counter')::bigint,backed_up=(a->>'backed_up')::boolean where id=k.id;
 insert into ecb_governance.sessions(scope,credential,ceremony,secret_hash,csrf_hash)
 values(s.id,k.id,c.id,a->>'secret_hash',a->>'csrf_hash') returning id into r;
 end if;
 update ecb_governance.ceremonies set proof=a->'proof',consumed_at=clock_timestamp() where id=c.id;
 return jsonb_build_object('id',r);
 elsif action='bind' then
 select jsonb_agg(jsonb_build_object('id',id,'credential_id',credential_id,'public_key',public_key) order by id) into keys from ecb_governance.credentials where scope=s.id;
 if jsonb_array_length(keys) is distinct from s.credential_count or ecb_governance.hash(keys::text) is distinct from a->>'credential_set_digest' then raise exception 'binding_changed'; end if;
 b:=ecb_governance.retain('binding',jsonb_build_object('scope',s.id,'h',s.h,'remit',s.remit,'p0',s.p0,'root_basis',s.root_basis,'credentials',keys,'rp_id',s.rp_id,'origin',s.origin)::text,'protected human setup completion');
 update ecb_governance.scopes set binding=b where id=s.id;
 insert into ecb_governance.decisions(scope,operation,policy,basis,h,explanation,request_id,fingerprint)
 values(s.id,'genesis',s.p0,s.root_basis,s.h,'Exact credential and scope binding completed through commissioned setup',(a->>'request_id')::uuid,ecb_governance.hash((a-'setup_secret')::text)) returning id into r;
 return jsonb_build_object('decision',r,'binding',b,'activated',false);
 elsif action='binding_digest' then
 perform ecb_governance.check_setup(s,a->>'setup_secret');
 select jsonb_agg(jsonb_build_object('id',id,'credential_id',credential_id,'public_key',public_key) order by id) into keys from ecb_governance.credentials where scope=s.id;
 return jsonb_build_object('digest',ecb_governance.hash(keys::text),'credentials',keys);
 end if;
 ss:=ecb_governance.check_session(s.id,a->>'session_secret',a->>'csrf',action<>'view');
 if action='view' then return ecb_governance.view_scope(s.id)||jsonb_build_object('session',jsonb_build_object('absolute_expires',ss.absolute_expires,'idle_expires',ss.last_active+interval '24 hours'));
 elsif action='logout' then update ecb_governance.sessions set invalidated_at=clock_timestamp() where id=ss.id; return jsonb_build_object('logged_out',true);
 elsif action not in ('accept','decline','withdraw') then raise exception 'unsupported_operation'; end if;
 if s.current_transition is null then raise exception 'governance_inactive'; end if;
 fp:=ecb_governance.hash((a-'session_secret'-'csrf')::text||action);
 select * into d from ecb_governance.decisions where scope=s.id and request_id=(a->>'request_id')::uuid;
 if found then if d.fingerprint<>fp then raise exception 'request_conflict'; end if; return to_jsonb(d); end if;
 select * into prior from ecb_governance.transitions where id=s.current_transition;
 if action='withdraw' then
 select * into d from ecb_governance.decisions where id=(a->>'decision')::uuid and scope=s.id and operation='succession' and h=s.h;
 if not found then raise exception 'not_own_pending_decision'; end if;
 select id into r from ecb_governance.transitions where decision=d.id;
 if found then return jsonb_build_object('already_completed',r); end if;
 if exists(select 1 from ecb_governance.decisions where target=d.id and operation='withdraw') then raise exception 'already_withdrawn'; end if;
 insert into ecb_governance.decisions(scope,operation,predecessor,basis,h,session_id,target,explanation,request_id,fingerprint)
 values(s.id,'withdraw',s.current_transition,s.current_transition,s.h,ss.id,d.id,coalesce(a->>'explanation',''),(a->>'request_id')::uuid,fp) returning id into r;
 else
 if s.current_transition is distinct from (a->>'predecessor')::uuid then raise exception 'stale_predecessor'; end if;
 select ecb_governance.policy(payload) into cp from ecb_governance.subjects where id=prior.policy;
 if (cp->>'requires_human_explanation')::boolean and length(trim(coalesce(a->>'explanation','')))=0 then raise exception 'explanation_required'; end if;
 if ecb_governance.hash(a->>'policy_bytes') is distinct from a->>'policy_digest' then raise exception 'wrong_digest'; end if;
 p:=ecb_governance.retain('policy',a->>'policy_bytes','exact human session decision');
 insert into ecb_governance.decisions(scope,operation,policy,predecessor,basis,h,session_id,explanation,request_id,fingerprint)
 values(s.id,case action when 'accept' then 'succession' else 'decline' end,p,s.current_transition,s.current_transition,s.h,ss.id,coalesce(a->>'explanation',''),(a->>'request_id')::uuid,fp) returning id into r;
 end if;
 return (select to_jsonb(x) from ecb_governance.decisions x where id=r);
end $function$

CREATE OR REPLACE FUNCTION public.prepare_build_5b_artifact()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  installed_definition text;
  installed_definition_digest text;
  contract_obligations text[] := array[
    'input_format', 'output_format', 'participation', 'grounding', 'preservation', 'checker_binding'
  ];
  checker_identity text := 'prepare_build_5b_artifact/v1';
  context_row public.artifacts%rowtype;
  operation_row public.artifacts%rowtype;
  input_row public.artifacts%rowtype;
  output_row public.artifacts%rowtype;
  output_found boolean := false;
  operation_spec jsonb;
  derived_payload jsonb;

  -- receipt working state
  check_input_format boolean;
  check_output_format boolean;
  check_participation boolean;
  check_grounding boolean;
  check_preservation boolean;
  check_binding boolean;
  reason_map jsonb := '{}'::jsonb;
  witness jsonb;
  result_text text;

  input_doc json;
  output_doc json;
  input_ok boolean := false;
  output_ok boolean := false;

  -- witness columns
  w_event uuid;
  w_claim uuid;
  w_from text;
  w_to text;
  w_recorded timestamptz;
  w_link uuid;
  w_evidence uuid;
  w_scheme text;
  w_linked_digest bytea;
  w_observed_digest bytea;
  w_link_claim uuid;
  witness_found boolean := false;

  uuid_pattern text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  hex64_pattern text := '^[0-9a-f]{64}$';
  ts_pattern text := '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}Z$';

  queue json[];
  cursor_node json;
  key_total bigint;
  key_distinct bigint;
begin
  -- Derived columns are never caller-supplied. The grant boundary already withholds them from
  -- service_role; this rejects a forged value from any role that can reach the table at all.
  if new.payload_digest is not null
     or new.recorded_at is not null
     or new.created_xid is not null then
    raise exception 'BUILD 5B derived columns are not caller-insertable'
      using errcode = '42501';
  end if;

  if new.id is null then
    new.id := pg_catalog.gen_random_uuid();
  end if;

  if new.artifact_role is null then
    raise exception 'BUILD 5B artifact_role is required' using errcode = '23514';
  end if;

  -- The installed checker definition, obtained by database introspection rather than asserted.
  select pg_catalog.pg_get_functiondef(p.oid)
    into installed_definition
  from pg_catalog.pg_proc p
  join pg_catalog.pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'public'
    and p.proname = 'prepare_build_5b_artifact';

  if installed_definition is null then
    raise exception 'BUILD 5B checker definition is not introspectable' using errcode = 'P0002';
  end if;

  installed_definition_digest := pg_catalog.encode(
    extensions.digest(pg_catalog.convert_to(installed_definition, 'UTF8'), 'sha256'), 'hex');

  -- Native participation resolution. A representation's context is a bare Referent; every other
  -- role's context must be an existing Artifact of the required role.
  if new.artifact_role <> 'source_representation' then
    select * into context_row from public.artifacts where id = new.context_id;
    if not found then
      raise exception 'BUILD 5B context % is not an Artifact', new.context_id
        using errcode = '23503';
    end if;
  end if;

  if new.artifact_role in ('source_representation', 'transformed_representation') then
    if new.payload_text is null then
      raise exception 'BUILD 5B % requires caller payload', new.artifact_role
        using errcode = '23514';
    end if;
  else
    if new.payload_text is not null then
      raise exception 'BUILD 5B % payload is database-derived', new.artifact_role
        using errcode = '42501';
    end if;
  end if;

  if new.artifact_role = 'source_representation' then
    -- Its purported Event/source contents are checked later, so wrong or missing native evidence
    -- stays observable rather than being erased at write time.
    null;

  elsif new.artifact_role = 'transformation_request' then
    if context_row.artifact_role <> 'source_representation' then
      raise exception 'BUILD 5B request context must be a source_representation'
        using errcode = '23514';
    end if;

    operation_spec := pg_catalog.jsonb_build_object(
      'contract_id', 'ecb_transition_relayout_v1',
      'contract_version', 1,
      'source_format', 'transition_v1',
      'output_format', 'basis_v1',
      'scope', 'recorded_transition_only',
      'coverage', 'grounding_and_preservation',
      'obligations', pg_catalog.to_jsonb(contract_obligations),
      'checker_id', checker_identity,
      'checker_definition', installed_definition,
      'checker_definition_digest', installed_definition_digest,
      'trust_boundary',
        'service_role_producer; trusted_database_and_ddl; no_external_trust_root'
    );
    new.payload_text := operation_spec::text;

  elsif new.artifact_role = 'transformed_representation' then
    if context_row.artifact_role <> 'transformation_request' then
      raise exception 'BUILD 5B output context must be a transformation_request'
        using errcode = '23514';
    end if;
    -- Payload may be malformed. Exact bytes are retained and never silently corrected.

  elsif new.artifact_role = 'check_attempt' then
    if context_row.artifact_role <> 'transformation_request' then
      raise exception 'BUILD 5B attempt context must be a transformation_request'
        using errcode = '23514';
    end if;

    select * into input_row from public.artifacts where id = context_row.context_id;
    if not found then
      raise exception 'BUILD 5B attempt input is unavailable' using errcode = 'P0002';
    end if;

    -- The target must be registered; it need not yet have a native output row.
    derived_payload := pg_catalog.jsonb_build_object(
      'event', 'check_requested',
      'operation_id', context_row.id,
      'operation_digest', pg_catalog.encode(context_row.payload_digest, 'hex'),
      'input_id', input_row.id,
      'input_digest', pg_catalog.encode(input_row.payload_digest, 'hex'),
      'output_id', new.target_id,
      'contract_id', 'ecb_transition_relayout_v1',
      'checker_id', checker_identity,
      'checker_definition_digest', installed_definition_digest
    );
    new.payload_text := derived_payload::text;

  elsif new.artifact_role = 'transformation_receipt' then
    if context_row.artifact_role <> 'check_attempt' then
      raise exception 'BUILD 5B receipt context must be a check_attempt'
        using errcode = '23514';
    end if;

    -- Committed-attempt entry boundary. pg_current_xact_id() returns the top-level transaction id
    -- even inside a subtransaction, so a SAVEPOINT cannot bypass this.
    if context_row.created_xid = pg_catalog.pg_current_xact_id() then
      raise exception
        'BUILD 5B receipt requires an attempt committed in a different top-level transaction'
        using errcode = '55000';
    end if;

    select * into operation_row from public.artifacts where id = context_row.context_id;
    if not found then
      raise exception 'BUILD 5B receipt operation is unavailable' using errcode = 'P0002';
    end if;

    select * into input_row from public.artifacts where id = operation_row.context_id;
    if not found then
      raise exception 'BUILD 5B receipt input is unavailable' using errcode = 'P0002';
    end if;

    select * into output_row from public.artifacts where id = context_row.target_id;
    output_found := found;

    ---------------------------------------------------------------------------
    -- checker_binding, evaluated first. An unqualified checker is unavailable
    -- checking capability, never an invented result under another contract.
    ---------------------------------------------------------------------------
    if operation_row.payload_text::jsonb ->> 'checker_id' = checker_identity
       and operation_row.payload_text::jsonb ->> 'checker_definition_digest'
           = installed_definition_digest then
      check_binding := true;
    else
      check_binding := null;
      reason_map := reason_map
        || pg_catalog.jsonb_build_object('checker_binding', 'checker_definition_mismatch');
    end if;

    if check_binding is true then
      -----------------------------------------------------------------------
      -- input_format
      -----------------------------------------------------------------------
      begin
        input_doc := input_row.payload_text::json;
        input_ok := true;
      exception
        when others then
          input_ok := false;
      end;

      if not input_ok then
        check_input_format := false;
      else
        check_input_format := true;
        -- Duplicate keys at every depth, tested on json before jsonb can discard them.
        queue := array[input_doc];
        while pg_catalog.array_length(queue, 1) > 0 loop
          cursor_node := queue[1];
          queue := queue[2:];
          if pg_catalog.json_typeof(cursor_node) = 'object' then
            select pg_catalog.count(*), pg_catalog.count(distinct k)
              into key_total, key_distinct
            from pg_catalog.json_object_keys(cursor_node) as t(k);
            if key_total <> key_distinct then
              check_input_format := false;
              exit;
            end if;
            queue := queue || array(select value from pg_catalog.json_each(cursor_node));
          elsif pg_catalog.json_typeof(cursor_node) = 'array' then
            queue := queue || array(select value from pg_catalog.json_array_elements(cursor_node));
          end if;
        end loop;
      end if;

      if check_input_format then
        check_input_format :=
          (select pg_catalog.count(*) from pg_catalog.json_object_keys(input_doc)) = 8
          and input_doc ->> 'format' = 'transition_v1'
          and input_doc ->> 'scope' = 'recorded_transition_only'
          and pg_catalog.json_typeof(input_doc -> 'basis') = 'object'
          and (select pg_catalog.count(*) from pg_catalog.json_object_keys(input_doc -> 'basis')) = 5
          and (input_doc ->> 'event') ~ uuid_pattern
          and (input_doc ->> 'claim') ~ uuid_pattern
          and pg_catalog.json_typeof(input_doc -> 'from') = 'string'
          and pg_catalog.json_typeof(input_doc -> 'to') = 'string'
          and (input_doc ->> 'recorded_at') ~ ts_pattern
          and (input_doc #>> '{basis,link}') ~ uuid_pattern
          and (input_doc #>> '{basis,evidence}') ~ uuid_pattern
          and pg_catalog.json_typeof(input_doc #> '{basis,scheme}') = 'string'
          and (input_doc #>> '{basis,linked_digest}') ~ hex64_pattern
          and (input_doc #>> '{basis,observed_digest}') ~ hex64_pattern;
      end if;

      if check_input_format is not true then
        check_input_format := false;
        reason_map := reason_map
          || pg_catalog.jsonb_build_object('input_format', 'invalid_format');
      end if;

      -----------------------------------------------------------------------
      -- output_format and participation
      -----------------------------------------------------------------------
      if not output_found then
        check_output_format := null;
        check_participation := null;
        reason_map := reason_map || pg_catalog.jsonb_build_object(
          'output_format', 'unavailable', 'participation', 'unavailable');
      else
        if output_row.artifact_role = 'transformed_representation'
           and output_row.context_id = operation_row.id then
          check_participation := true;
        else
          check_participation := false;
          reason_map := reason_map
            || pg_catalog.jsonb_build_object('participation', 'wrong_participant');
        end if;

        begin
          output_doc := output_row.payload_text::json;
          output_ok := true;
        exception
          when others then
            output_ok := false;
        end;

        if not output_ok then
          check_output_format := false;
        else
          check_output_format := true;
          queue := array[output_doc];
          while pg_catalog.array_length(queue, 1) > 0 loop
            cursor_node := queue[1];
            queue := queue[2:];
            if pg_catalog.json_typeof(cursor_node) = 'object' then
              select pg_catalog.count(*), pg_catalog.count(distinct k)
                into key_total, key_distinct
              from pg_catalog.json_object_keys(cursor_node) as t(k);
              if key_total <> key_distinct then
                check_output_format := false;
                exit;
              end if;
              queue := queue || array(select value from pg_catalog.json_each(cursor_node));
            elsif pg_catalog.json_typeof(cursor_node) = 'array' then
              queue := queue || array(select value from pg_catalog.json_array_elements(cursor_node));
            end if;
          end loop;
        end if;

        if check_output_format then
          check_output_format :=
            (select pg_catalog.count(*) from pg_catalog.json_object_keys(output_doc)) = 4
            and output_doc ->> 'format' = 'basis_v1'
            and output_doc ->> 'scope' = 'recorded_transition_only'
            and pg_catalog.json_typeof(output_doc -> 'basis') = 'object'
            and pg_catalog.json_typeof(output_doc -> 'transition') = 'object'
            and (select pg_catalog.count(*)
                 from pg_catalog.json_object_keys(output_doc -> 'basis')) = 5
            and (select pg_catalog.count(*)
                 from pg_catalog.json_object_keys(output_doc -> 'transition')) = 5
            and (output_doc #>> '{basis,evidence}') ~ uuid_pattern
            and (output_doc #>> '{basis,link}') ~ uuid_pattern
            and pg_catalog.json_typeof(output_doc #> '{basis,scheme}') = 'string'
            and (output_doc #>> '{basis,linked_digest}') ~ hex64_pattern
            and (output_doc #>> '{basis,observed_digest}') ~ hex64_pattern
            and (output_doc #>> '{transition,id}') ~ uuid_pattern
            and (output_doc #>> '{transition,claim}') ~ uuid_pattern
            and pg_catalog.json_typeof(output_doc #> '{transition,from}') = 'string'
            and pg_catalog.json_typeof(output_doc #> '{transition,to}') = 'string'
            and (output_doc #>> '{transition,recorded_at}') ~ ts_pattern;
        end if;

        if check_output_format is not true then
          check_output_format := false;
          reason_map := reason_map
            || pg_catalog.jsonb_build_object('output_format', 'invalid_format');
        end if;
      end if;

      -----------------------------------------------------------------------
      -- grounding, against a separately read source witness
      -----------------------------------------------------------------------
      select t.id, t.claim_id, t.from_standing, t.to_standing, t.recorded_at,
             l.id, l.evidence_referent_id, l.evidence_revision_scheme,
             l.evidence_revision_digest, t.observed_revision_digest, l.claim_id
        into w_event, w_claim, w_from, w_to, w_recorded,
             w_link, w_evidence, w_scheme, w_linked_digest, w_observed_digest, w_link_claim
      from public.claim_standing_transitions t
      left join public.evidence_links l on l.id = t.basis_evidence_link_id
      where t.id = input_row.context_id;
      witness_found := found;

      if witness_found and w_link is not null then
        witness := pg_catalog.jsonb_build_object(
          'event_id', w_event,
          'claim_id', w_claim,
          'from_standing', w_from,
          'to_standing', w_to,
          'recorded_at', pg_catalog.to_char(
            w_recorded at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
          'link_id', w_link,
          'evidence_referent_id', w_evidence,
          'evidence_revision_scheme', w_scheme,
          'evidence_revision_digest', pg_catalog.encode(w_linked_digest, 'hex'),
          'observed_revision_digest', pg_catalog.encode(w_observed_digest, 'hex'),
          'link_claim_id', w_link_claim
        );
      else
        witness := null;
      end if;

      if not check_input_format then
        check_grounding := null;
        reason_map := reason_map
          || pg_catalog.jsonb_build_object('grounding', 'not_evaluated');
      elsif witness is null then
        check_grounding := null;
        reason_map := reason_map
          || pg_catalog.jsonb_build_object('grounding', 'unavailable');
      else
        check_grounding :=
          (input_doc ->> 'event') = w_event::text
          and (input_doc ->> 'claim') = w_claim::text
          and (input_doc ->> 'from') = w_from
          and (input_doc ->> 'to') = w_to
          and (input_doc ->> 'recorded_at') = (witness ->> 'recorded_at')
          and (input_doc #>> '{basis,link}') = w_link::text
          and (input_doc #>> '{basis,evidence}') = w_evidence::text
          and (input_doc #>> '{basis,scheme}') = w_scheme
          and (input_doc #>> '{basis,linked_digest}')
              = pg_catalog.encode(w_linked_digest, 'hex')
          and (input_doc #>> '{basis,observed_digest}')
              = pg_catalog.encode(w_observed_digest, 'hex')
          -- A present but inconsistent Link is a grounding failure, not a filtered-out row.
          and w_link_claim = w_claim;
        if not check_grounding then
          reason_map := reason_map
            || pg_catalog.jsonb_build_object('grounding', 'mismatch');
        end if;
      end if;

      -----------------------------------------------------------------------
      -- preservation
      -----------------------------------------------------------------------
      if check_input_format is not true or check_output_format is not true then
        check_preservation := null;
        reason_map := reason_map
          || pg_catalog.jsonb_build_object('preservation', 'not_evaluated');
      else
        check_preservation :=
          (output_doc #>> '{transition,id}') = (input_doc ->> 'event')
          and (output_doc #>> '{transition,claim}') = (input_doc ->> 'claim')
          and (output_doc #>> '{transition,from}') = (input_doc ->> 'from')
          and (output_doc #>> '{transition,to}') = (input_doc ->> 'to')
          and (output_doc #>> '{transition,recorded_at}') = (input_doc ->> 'recorded_at')
          and (output_doc #>> '{basis,link}') = (input_doc #>> '{basis,link}')
          and (output_doc #>> '{basis,evidence}') = (input_doc #>> '{basis,evidence}')
          and (output_doc #>> '{basis,scheme}') = (input_doc #>> '{basis,scheme}')
          and (output_doc #>> '{basis,linked_digest}') = (input_doc #>> '{basis,linked_digest}')
          and (output_doc #>> '{basis,observed_digest}')
              = (input_doc #>> '{basis,observed_digest}')
          and (output_doc ->> 'scope') = (input_doc ->> 'scope');
        if not check_preservation then
          reason_map := reason_map
            || pg_catalog.jsonb_build_object('preservation', 'mismatch');
        end if;
      end if;
    else
      -- Unqualified checker: do not evaluate further under another contract.
      check_input_format := null;
      check_output_format := null;
      check_participation := null;
      check_grounding := null;
      check_preservation := null;
      witness := null;
      reason_map := reason_map || pg_catalog.jsonb_build_object(
        'input_format', 'not_evaluated',
        'output_format', 'not_evaluated',
        'participation', 'not_evaluated',
        'grounding', 'not_evaluated',
        'preservation', 'not_evaluated'
      );
    end if;

    -- Any observed false yields FAIL even when other components are unavailable; otherwise any
    -- null yields INCOMPLETE; only all six true yields PASS. producer_succeeded has no weight.
    if check_input_format is false or check_output_format is false
       or check_participation is false or check_grounding is false
       or check_preservation is false or check_binding is false then
      result_text := 'FAIL';
    elsif check_input_format is null or check_output_format is null
       or check_participation is null or check_grounding is null
       or check_preservation is null or check_binding is null then
      result_text := 'INCOMPLETE';
    else
      result_text := 'PASS';
    end if;

    derived_payload := pg_catalog.jsonb_build_object(
      'receipt_version', 1,
      'scope', 'recorded_transition_only',
      'coverage', 'grounding_and_preservation',
      'attempt_id', context_row.id,
      'operation_id', operation_row.id,
      'input_id', input_row.id,
      'output_id', context_row.target_id,
      'operation_digest', pg_catalog.encode(operation_row.payload_digest, 'hex'),
      'input_digest', pg_catalog.encode(input_row.payload_digest, 'hex'),
      'output_digest', case when output_found
        then pg_catalog.encode(output_row.payload_digest, 'hex') else null end,
      'checker_id', checker_identity,
      'checker_definition_digest',
        operation_row.payload_text::jsonb ->> 'checker_definition_digest',
      'observed_checker_definition_digest', installed_definition_digest,
      'producer_succeeded', case when output_found
        then pg_catalog.to_jsonb(output_row.producer_succeeded) else 'null'::jsonb end,
      'checks', pg_catalog.jsonb_build_object(
        'input_format', check_input_format,
        'output_format', check_output_format,
        'participation', check_participation,
        'grounding', check_grounding,
        'preservation', check_preservation,
        'checker_binding', check_binding
      ),
      'reasons', reason_map,
      'source_witness', witness,
      'result', result_text
    );
    new.payload_text := derived_payload::text;
  end if;

  -- Fresh same-UUID Referent registration. An already-registered id is rejected, matching the
  -- fresh-native creation posture; this installs no general native-binding lifecycle.
  if exists (select 1 from public.referents where id = new.id) then
    raise exception 'BUILD 5B Artifact id % is already registered', new.id
      using errcode = '23505';
  end if;
  insert into public.referents (id) values (new.id);

  new.payload_digest := extensions.digest(
    pg_catalog.convert_to(new.payload_text, 'UTF8'), 'sha256');
  new.recorded_at := pg_catalog.transaction_timestamp();
  new.created_xid := pg_catalog.pg_current_xact_id();

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.prepare_claim()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  insert into public.referents (id)
  values (new.id);

  new.origin := 'ecb_inference';
  new.epistemic_standing := 'unassessed';
  new.asserted_at := pg_catalog.transaction_timestamp();

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.prepare_claim_standing_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  basis_claim_id uuid;
  basis_evidence_referent_id uuid;
  applied_standing text;
begin
  insert into public.referents (id)
  values (new.id);

  select link.claim_id, link.evidence_referent_id
  into strict basis_claim_id, basis_evidence_referent_id
  from public.evidence_links as link
  where link.id = new.basis_evidence_link_id;

  if basis_claim_id <> new.claim_id then
    raise exception
      'BUILD 5A basis Evidence Link % does not declare a basis for Claim %',
      new.basis_evidence_link_id, new.claim_id
      using errcode = '23514';
  end if;

  select claim.epistemic_standing
  into strict applied_standing
  from public.claims as claim
  where claim.id = new.claim_id
  for update;

  if applied_standing <> new.from_standing then
    raise exception
      'BUILD 5A declared prior standing % does not match applied standing %',
      new.from_standing, applied_standing
      using errcode = '40001';
  end if;

  new.observed_revision_digest :=
    public.thought_revision_digest(basis_evidence_referent_id);
  new.recorded_at := pg_catalog.transaction_timestamp();

  update public.claims
  set epistemic_standing = new.to_standing
  where id = new.claim_id;

  return new;
exception
  when no_data_found then
    raise exception
      'BUILD 5A subject Claim or basis Evidence Link is unavailable'
      using errcode = 'P0002';
end;
$function$

CREATE OR REPLACE FUNCTION public.prepare_evidence_link()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  evidence_content text;
  evidence_source text;
  evidence_captured_at timestamptz;
  content_octets bytea;
  source_octets bytea;
  captured_at_microseconds bigint;
  digest_input bytea;
begin
  select thought.content, thought.source, thought.captured_at
  into strict evidence_content, evidence_source, evidence_captured_at
  from public.thoughts as thought
  where thought.id = new.evidence_referent_id
  for share;

  if not pg_catalog.isfinite(evidence_captured_at) then
    raise exception 'BUILD 3 evidence captured_at must be finite'
      using errcode = '22008';
  end if;

  content_octets := pg_catalog.convert_to(evidence_content, 'UTF8');
  source_octets := pg_catalog.convert_to(evidence_source, 'UTF8');
  captured_at_microseconds :=
    (extract(epoch from evidence_captured_at) * 1000000)::bigint;

  digest_input :=
    pg_catalog.convert_to('ECB-THOUGHT-REVISION-V1', 'UTF8')
    || pg_catalog.decode('00', 'hex')
    || pg_catalog.decode('01', 'hex')
    || pg_catalog.int8send(pg_catalog.octet_length(content_octets)::bigint)
    || content_octets
    || pg_catalog.decode('02', 'hex')
    || pg_catalog.int8send(pg_catalog.octet_length(source_octets)::bigint)
    || source_octets
    || pg_catalog.decode('03', 'hex')
    || pg_catalog.int8send(8::bigint)
    || pg_catalog.int8send(captured_at_microseconds);

  insert into public.referents (id)
  values (new.id);

  new.role := 'used_as_basis';
  new.evidence_revision_scheme := 'ecb_thought_revision_v1_sha256';
  new.evidence_revision_digest := extensions.digest(digest_input, 'sha256');
  new.linked_at := pg_catalog.transaction_timestamp();

  return new;
exception
  when no_data_found then
    raise exception 'BUILD 3 evidence Thought % is unavailable', new.evidence_referent_id
      using errcode = 'P0002';
end;
$function$

CREATE OR REPLACE FUNCTION public.thought_revision_digest(evidence_referent_id uuid)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  evidence_content text;
  evidence_source text;
  evidence_captured_at timestamptz;
  content_octets bytea;
  source_octets bytea;
  captured_at_microseconds bigint;
  digest_input bytea;
begin
  select thought.content, thought.source, thought.captured_at
  into strict evidence_content, evidence_source, evidence_captured_at
  from public.thoughts as thought
  where thought.id = evidence_referent_id
  for share;

  if not pg_catalog.isfinite(evidence_captured_at) then
    raise exception 'BUILD 5A evidence captured_at must be finite'
      using errcode = '22008';
  end if;

  content_octets := pg_catalog.convert_to(evidence_content, 'UTF8');
  source_octets := pg_catalog.convert_to(evidence_source, 'UTF8');
  captured_at_microseconds :=
    (extract(epoch from evidence_captured_at) * 1000000)::bigint;

  digest_input :=
    pg_catalog.convert_to('ECB-THOUGHT-REVISION-V1', 'UTF8')
    || pg_catalog.decode('00', 'hex')
    || pg_catalog.decode('01', 'hex')
    || pg_catalog.int8send(pg_catalog.octet_length(content_octets)::bigint)
    || content_octets
    || pg_catalog.decode('02', 'hex')
    || pg_catalog.int8send(pg_catalog.octet_length(source_octets)::bigint)
    || source_octets
    || pg_catalog.decode('03', 'hex')
    || pg_catalog.int8send(8::bigint)
    || pg_catalog.int8send(captured_at_microseconds);

  return extensions.digest(digest_input, 'sha256');
exception
  when no_data_found then
    raise exception 'BUILD 5A evidence Thought % is unavailable', evidence_referent_id
      using errcode = 'P0002';
end;
$function$
